const input = $json.body ?? $json;
const classification = String(input.classification ?? input.seller_response_classification ?? '').toLowerCase();
const counteroffer = Number(input.counteroffer_amount ?? input.counteroffer ?? input.accepted_price);
const dynamicMao = Number(input.dynamic_mao ?? input.adjusted_mao ?? input.mao);
const askingPrice = Number(input.asking_price);
const lastOffer = Number(input.last_offer_price ?? input.offer_price);
const motivation = Number(input.motivation_score);
const dealId = input.deal_id ?? null;
const leadId = input.lead_id ?? null;
const propertyId = input.property_id ?? null;
const blockers = Array.isArray(input.blockers) ? input.blockers : [];
const identityOk = Boolean(dealId && leadId && propertyId);
const withinMao = Number.isFinite(counteroffer) && Number.isFinite(dynamicMao) && counteroffer <= dynamicMao;
const nearMao = Number.isFinite(counteroffer) && Number.isFinite(dynamicMao) && counteroffer > dynamicMao && counteroffer <= dynamicMao * 1.05;
const materiallyAboveMao = Number.isFinite(counteroffer) && Number.isFinite(dynamicMao) && counteroffer > dynamicMao * 1.05;

let decision = 'needs_review';
let status = 'needs_review';
let nextWorkflow = 'WF-126';
let humanReview = true;
let strategy = 'review';

if (!identityOk || blockers.length) {
  decision = 'blocked';
  status = 'blocked';
} else if (classification === 'accepted') {
  decision = Number.isFinite(counteroffer) && Number.isFinite(dynamicMao) && counteroffer <= dynamicMao
    ? 'acceptance_ready'
    : 'acceptance_price_review';
  status = decision === 'acceptance_ready' ? 'accepted_within_mao' : 'accepted_price_review';
  nextWorkflow = decision === 'acceptance_ready' ? 'WF-267' : 'WF-126';
  humanReview = decision !== 'acceptance_ready';
  strategy = decision === 'acceptance_ready' ? 'move_to_contract' : 'verify_price';
} else if (classification === 'counteroffer') {
  if (withinMao) {
    decision = 'counteroffer_within_mao';
    status = 'negotiable_within_mao';
    nextWorkflow = 'WF-267';
    humanReview = true;
    strategy = 'evaluate_accept_or_revise';
  } else if (nearMao) {
    decision = 'counteroffer_near_mao';
    status = 'near_mao';
    nextWorkflow = 'WF-267';
    humanReview = true;
    strategy = 'protect_margin_and_consider_revised_offer';
  } else if (materiallyAboveMao) {
    decision = 'counteroffer_above_mao';
    status = 'above_mao';
    nextWorkflow = 'WF-268';
    humanReview = true;
    strategy = 'reengage_or_walk_away';
  }
} else if (classification === 'question') {
  decision = 'seller_question_follow_up';
  status = 'clarification_required';
  nextWorkflow = 'WF-269';
  humanReview = false;
  strategy = 'answer_then_continue_negotiation';
} else if (classification === 'rejected') {
  decision = 'rejection_reengagement';
  status = 'rejected';
  nextWorkflow = 'WF-261';
  humanReview = false;
  strategy = 'reengage';
} else if (classification === 'no_response') {
  decision = 'no_response_reengagement';
  status = 'no_response';
  nextWorkflow = 'WF-261';
  humanReview = false;
  strategy = 'cadence_reengagement';
} else {
  decision = 'other_response_review';
  status = 'other_response';
  nextWorkflow = 'WF-269';
  humanReview = false;
  strategy = 'clarify_and_continue';
}

const priceContext = {
  counteroffer: Number.isFinite(counteroffer) ? counteroffer : null,
  dynamic_mao: Number.isFinite(dynamicMao) ? dynamicMao : null,
  asking_price: Number.isFinite(askingPrice) ? askingPrice : null,
  last_offer: Number.isFinite(lastOffer) ? lastOffer : null,
  within_mao: withinMao,
  near_mao: nearMao,
  materially_above_mao: materiallyAboveMao
};

return [{ json: {
  ...input,
  workflow_id: 'WF-266',
  workflow_name: 'Seller Response → Negotiation Decision & Response Strategy Controller',
  decision,
  status,
  strategy,
  next_workflow: nextWorkflow,
  human_review_required: humanReview,
  price_context: priceContext,
  identity_valid: identityOk,
  blockers,
  negotiation_response: {
    objective: strategy,
    protect_dynamic_mao: true,
    seller_response_classification: classification
  },
  crm_activity: {
    activity_type: 'negotiation_decision',
    workflow_id: 'WF-266',
    decision,
    status,
    strategy,
    next_workflow: nextWorkflow,
    human_review_required: humanReview
  }
} }];
